function parseLedger(markdown) {
  // Brief 01: only the section whose heading line is exactly '## Transaction Ledger'
  // is authoritative. Ignore working-copy headings like '## Transaction Ledger (working copy)'.
  const startMatch = markdown.match(/^## Transaction Ledger\s*$/m);
  if (!startMatch || startMatch.index == null) return [];

  const start = startMatch.index;
  const afterStart = markdown.slice(start);
  // Stop at next top-level heading after this ledger section.
  const rest = afterStart.slice(startMatch[0].length);
  const nextTop = rest.match(/^##\s+/m);
  const slice = nextTop ? afterStart.slice(0, startMatch[0].length + nextTop.index) : afterStart;

  const rows = [];
  const blocks = slice.split(/^### /m).slice(1);
  for (const block of blocks) {
    if (/^provisional:\s*true\s*$/im.test(block)) continue; // Brief 01

    const lines = block.split("\n");
    const transactionId = lines[0].trim();
    if (!transactionId.startsWith("TXN-")) continue;

    const row = { transaction_id: transactionId };
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith("amount:")) row.amount = Number(trimmed.split(":")[1].trim());
      else if (trimmed.startsWith("owner:")) row.owner = trimmed.split(":")[1].trim();
      else if (trimmed.startsWith("status:")) row.status = trimmed.split(":")[1].trim();
      else if (trimmed.startsWith("date:")) row.date = trimmed.split(":")[1].trim();
    }
    rows.push(row);
  }

  // Brief 01: if same TXN appears multiple times (non-provisional), last in file order wins.
  // reconcile.js uses a Map set in iteration order, so returning in file order is sufficient.
  return rows;
}

module.exports = { parseLedger };
