const { sortByTransactionId } = require("../utils/sort");

const STATUS_ORDER = { pending: 0, approved: 1, rejected: 2, reversed: 3 };

function maxStatus(current, incoming) {
  const c = STATUS_ORDER[String(current).toLowerCase()] ?? -1;
  const n = STATUS_ORDER[String(incoming).toLowerCase()] ?? -1;
  return n > c ? incoming : current;
}

function reconcileTransactions(parsed) {
  const byId = new Map();
  for (const row of parsed.ledger) {
    // Brief 01: last non-provisional ledger block wins, so later set overwrites.
    byId.set(row.transaction_id, { ...row });
  }

  // Apply meeting amendments (Brief 05)
  for (const meeting of parsed.meetings) {
    const target = byId.get(meeting.transaction_id);
    if (!target) continue;

    const signed = String(meeting.signed).toLowerCase() === "true";
    if (!signed) continue;

    if (meeting.effective) {
      if (String(meeting.effective) < String(target.date)) continue;
    }

    if (meeting.owner) target.owner = meeting.owner;
  }

  // Apply compliance emails (Brief 02 + Brief 03)
  const preCorrection = new Map();
  for (const email of parsed.emails) {
    const target = byId.get(email.transaction_id);
    if (!target) continue;

    if (!String(email.from_addr).includes("compliance@")) continue;

    if (email.sent) {
      if (String(email.sent) < String(target.date)) continue;
    }

    target.status = maxStatus(target.status, email.status);
  }

  // Snapshot state for Brief 09 (hold flag): after ledger+meetings+mail, before corrections.
  for (const [id, row] of byId.entries()) {
    preCorrection.set(id, { date: row.date, status: row.status });
  }

  // Brief 04: winning correction per (transaction, field) has lexicographically greatest effective date.
  const winByKey = new Map();
  for (const notice of parsed.corrections) {
    const key = `${notice.transaction_id}::${notice.field}`;
    const prev = winByKey.get(key);
    if (!prev || String(notice.effective) > String(prev.effective)) {
      winByKey.set(key, notice);
    }
  }

  const winners = [...winByKey.values()].sort((a, b) => {
    if (a.effective === b.effective) return a.notice_id < b.notice_id ? -1 : 1;
    return a.effective < b.effective ? -1 : 1;
  });

  const report = [];
  const effectiveByTxn = new Map();
  const statusChangedByCorrection = new Set();

  for (const notice of winners) {
    const target = byId.get(notice.transaction_id);
    if (!target) continue;

    const prevVal = String(target[notice.field] ?? "");

    if (notice.field === "owner") {
      target.owner = notice.value;
    } else if (notice.field === "status") {
      if (String(target.status) !== String(notice.value)) statusChangedByCorrection.add(notice.transaction_id);
      target.status = notice.value;
      effectiveByTxn.set(notice.transaction_id, notice.effective);
    } else if (notice.field === "date") {
      if (String(target.date) !== String(notice.value)) effectiveByTxn.set(notice.transaction_id, notice.effective);
      target.date = notice.value;
    }

    report.push({
      notice_id: notice.notice_id,
      transaction_id: notice.transaction_id,
      field: notice.field,
      previous_value: prevVal,
      new_value: String(notice.value),
      effective: notice.effective,
    });
  }

  report.sort((a, b) => (a.notice_id < b.notice_id ? -1 : 1));

  const items = sortByTransactionId(
    [...byId.values()].map((row) => ({
      transaction_id: row.transaction_id,
      owner: row.owner,
      status: String(row.status).toLowerCase(),
      effective_date: effectiveByTxn.get(row.transaction_id) ?? row.date,
      amount_usd: Number(Number(row.amount).toFixed(2)),
      exception_reason: null,
    })),
  );

  return {
    items,
    report,
    meta: {
      preCorrection,
      statusChangedByCorrection,
    },
  };
}

module.exports = { reconcileTransactions, STATUS_ORDER };
