function buildExceptions(items, parsed, meta) {
  const policyIds = parsed.policyExceptions;
  const preCorrection = meta?.preCorrection;
  const statusChangedByCorrection = meta?.statusChangedByCorrection ?? new Set();

  const complianceEmails = parsed.emails.filter(
    (e) => String(e.from_addr).includes("compliance@") && e.sent,
  );

  for (const row of items) {
    const codes = [];

    // Brief 07
    if (row.amount_usd > 10000) codes.push("over_limit");

    // Brief 09 governs the hold flag date comparison; requires a sent: line.
    const pre = preCorrection?.get(row.transaction_id);
    if (pre?.date) {
      const held = complianceEmails.some(
        (e) =>
          e.transaction_id === row.transaction_id && String(e.sent) < String(pre.date),
      );
      if (held) codes.push("compliance_hold");
    }

    // Brief 08
    if (
      row.status === "approved" &&
      row.amount_usd > 10000 &&
      policyIds &&
      policyIds.has(row.transaction_id)
    ) {
      codes.push("policy_waiver");
    }

    if (
      row.status === "reversed" &&
      row.amount_usd > 5000 &&
      statusChangedByCorrection.has(row.transaction_id)
    ) {
      codes.push("retroactive_review");
    }

    if (codes.length) {
      codes.sort();
      row.exception_reason = codes.join(";");
    } else {
      row.exception_reason = null;
    }
  }

  return items.filter((row) => row.exception_reason);
}

module.exports = { buildExceptions };
